import SwiftUI

/// The one entry point to the design system. Tokens keep their tokens.json names in `TaleedColor`,
/// `TaleedFont`, `TaleedSpacing`, `TaleedRadius`, `TaleedElevation`, `TaleedOpacity`, `TaleedSize`,
/// `TaleedLayout` and `TaleedMotion` (generated by scripts/generate-design-system.py).
enum Theme {
    typealias Colors = TaleedColor
    typealias Fonts = TaleedFont
    typealias Spacing = TaleedSpacing
    typealias Radius = TaleedRadius
    typealias Shadows = TaleedElevation
    typealias Sizes = TaleedSize
    typealias Motion = TaleedMotion

    /// `brand/primary`, also the app's tint.
    static let primary = TaleedColor.brandPrimary
    /// The smallest touch target (44 pt).
    static let minTouchTarget = TaleedSize.touchTargetMin
}

extension Color {
    /// A colour from a 24-bit sRGB hex value such as `0x2455F5`.
    init(taleedHex hex: UInt32, opacity: Double = 1) {
        self.init(
            .sRGB,
            red: Double((hex >> 16) & 0xFF) / 255,
            green: Double((hex >> 8) & 0xFF) / 255,
            blue: Double(hex & 0xFF) / 255,
            opacity: opacity
        )
    }
}

/// A drop shadow token. `blur` is the Figma (CSS) blur radius.
struct TaleedShadow: Sendable {
    let x: CGFloat
    let y: CGFloat
    let blur: CGFloat
    let color: Color
    let opacity: Double
}

extension View {
    /// Applies an elevation token.
    func taleedShadow(_ shadow: TaleedShadow) -> some View {
        self.shadow(color: shadow.color.opacity(shadow.opacity), radius: shadow.blur / 2, x: shadow.x, y: shadow.y)
    }

    /// `elevation.level0`: a 1 pt border in `border/subtle` (or another colour) around a rounded shape.
    func taleedBorder(_ color: Color = TaleedColor.borderSubtle, radius: CGFloat, width: CGFloat = 1) -> some View {
        overlay {
            RoundedRectangle(cornerRadius: radius, style: .continuous)
                .strokeBorder(color, lineWidth: width)
        }
    }

    /// Fill, border and corner radius in one go, the common card treatment.
    func taleedCard(
        fill: Color = TaleedColor.surfacePrimary,
        border: Color? = TaleedColor.borderSubtle,
        radius: CGFloat = TaleedRadius.m
    ) -> some View {
        background(fill, in: RoundedRectangle(cornerRadius: radius, style: .continuous))
            .overlay {
                if let border {
                    RoundedRectangle(cornerRadius: radius, style: .continuous).strokeBorder(border, lineWidth: 1)
                }
            }
    }

    /// Grows the tap area to 44 x 44 pt without changing the layout, for controls drawn smaller.
    func minimumHitArea(_ size: CGFloat = TaleedSize.touchTargetMin) -> some View {
        contentShape(MinimumHitShape(size: size))
    }
}

/// A rectangle at least `size` wide and high, centred on the view.
struct MinimumHitShape: Shape {
    var size: CGFloat

    func path(in rect: CGRect) -> Path {
        Path(rect.insetBy(dx: min(0, (rect.width - size) / 2), dy: min(0, (rect.height - size) / 2)))
    }
}
